// Block (composition) — a responsive grid of KPI cards.
// Card and Badge own their look; Grid and Stack own arrangement.
import type { Ref } from "react";
import { ArrowDown, ArrowUp } from "../components/icons";
import { Badge } from "../components/Badge";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./StatCardGrid.css";

export interface StatCardGridProps {
  /** KPI values to display as individual cards. */
  stats: {
    label: string;
    value: string;
    /** The change, with its sign ("+12%", "-8%"): the arrow is decorative, so the sign is what a
     *  screen reader hears, and the label and delta together must say whether it is bad news. */
    delta?: string;
    /** Which way the value moved. Direction only: it draws the arrow, never the colour. */
    trend?: "up" | "down" | "neutral";
    /**
     * Whether the move is good or bad news, which direction cannot say (falling refunds is good).
     * `negative` takes the `error` Badge, a change to act on. `positive` and unset both stay
     * `neutral`: good news needs no alarm, and `positive` records the meaning for the data's sake.
     */
    sentiment?: "positive" | "negative";
  }[];
  /** Responsive number of equal-width card columns. */
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function StatCardGrid({
  stats,
  columns = { small: 1, medium: 3 },
  className,
  ref,
}: StatCardGridProps) {
  return (
    <Grid
      ref={ref}
      columns={columns}
      gap="medium"
      className={className ? `sd-statcardgrid ${className}` : "sd-statcardgrid"}
    >
      {stats.map((stat) => (
        <Card key={stat.label}>
          <Stack gap="2x-small" align="start" className="sd-statcardgrid__content">
            <>
              <span className="sd-statcardgrid__label sd-type-label-medium">{stat.label}</span>
            </>
            <>
              <span className="sd-statcardgrid__value sd-type-headline-medium">{stat.value}</span>
            </>
            {stat.delta && (
              <Badge
                variant={stat.sentiment === "negative" ? "error" : "neutral"}
                icon={stat.trend === "up" ? <ArrowUp size="1em" /> : stat.trend === "down" ? <ArrowDown size="1em" /> : undefined}
              >
                {stat.delta}
              </Badge>
            )}
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* StatCardGrid.css — .sd-statcardgrid (Block)
   Arrangement only: Grid owns columns and gap; Card and Badge own their look. */
.sd-statcardgrid {
  width: 100%;
}

.sd-statcardgrid__value {
  /* A value that changes in place (a count, a percentage) keeps its width, so it does not jitter as
     its digits change. */
  font-variant-numeric: tabular-nums;
}
